verifier_source:
# Standalone verifier for a finite fragment of L1.
# No imports. Exact integer arithmetic only (rationals as (num, den>0),
# compared by cross-multiplication). No floats, no filesystem, no network,
# no printing, no caught exceptions. Fail closed: verify() raises
# SystemExit(1) on any failed check; a normal return means all checks passed.

def _norm(num, den):
    if type(num) is not int or type(den) is not int:
        raise SystemExit(1)
    if den == 0:
        raise SystemExit(1)
    if den < 0:
        num = -num
        den = -den
    return num, den

def _sgn(num, den):
    # exact sign of num/den via cross-multiplication against 0/1
    left = num * 1
    right = 0 * den
    if left > right:
        return 1
    if left < right:
        return -1
    return 0

def sign_exact(num, den):
    num, den = _norm(num, den)
    c = _sgn(num, den)
    if c > 0:
        return 'POSITIVE'
    if c < 0:
        return 'NEGATIVE'
    return 'ABORT'  # zero residual: nonzero sign not certifiable -> abort

def sign_interval(lo_num, lo_den, hi_num, hi_den):
    lo_num, lo_den = _norm(lo_num, lo_den)
    hi_num, hi_den = _norm(hi_num, hi_den)
    # enclosure must be well formed: lo <= hi, exact cross-multiplication
    if (lo_num * hi_den) > (hi_num * lo_den):
        return 'MALFORMED'
    lo_s = _sgn(lo_num, lo_den)
    hi_s = _sgn(hi_num, hi_den)
    if lo_s > 0:
        return 'POSITIVE'
    if hi_s < 0:
        return 'NEGATIVE'
    return 'ABORT'  # zero-straddling or touching zero -> abort per lemma

def check_case(c):
    k = c['kind']
    if k == 'exact':
        return sign_exact(c['num'], c['den'])
    if k == 'interval':
        r = sign_interval(c['lo_num'], c['lo_den'], c['hi_num'], c['hi_den'])
        if r == 'MALFORMED':
            raise SystemExit(1)
        return r
    if k == 'float_literal':
        if c['repr'] != 'FLOAT_LITERAL':
            raise SystemExit(1)
        return 'ABORT'  # float-literal input: abort per lemma
    if k == 'decimal_string':
        s = c['s']
        if 'e' in s or 'E' in s or '.' in s:
            raise SystemExit(1)  # exact integer-fraction form only
        parts = s.split('/')
        if len(parts) != 2:
            raise SystemExit(1)
        return sign_exact(int(parts[0]), int(parts[1]))
    raise SystemExit(1)

def verify(witness):
    cases = witness['cases']
    if len(cases) != 9:
        raise SystemExit(1)
    for c in cases:
        if check_case(c) != c['expected']:
            raise SystemExit(1)
    # direct checks of the sign logic, exact arithmetic only
    if sign_exact(7, 5) != 'POSITIVE':
        raise SystemExit(1)
    if sign_exact(-13, 3) != 'NEGATIVE':
        raise SystemExit(1)
    if sign_exact(0, 1) != 'ABORT':
        raise SystemExit(1)
    if sign_interval(11, 10, 6, 5) != 'POSITIVE':
        raise SystemExit(1)
    if sign_interval(-7, 2, -10, 3) != 'NEGATIVE':
        raise SystemExit(1)
    if sign_interval(-1, 2, 1, 2) != 'ABORT':
        raise SystemExit(1)
    if sign_interval(0, 1, 3, 7) != 'ABORT':
        raise SystemExit(1)
    if sign_interval(-10, 3, -7, 2) != 'NEGATIVE':
        raise SystemExit(1)
    # malformed enclosure must be reported, via flag, never a caught exception
    if sign_interval(3, 1, 2, 1) != 'MALFORMED':
        raise SystemExit(1)

WITNESS = {
 'cases': [
  {'kind': 'exact', 'num': 7, 'den': 5, 'expected': 'POSITIVE'},
  {'kind': 'exact', 'num': -13, 'den': 3, 'expected': 'NEGATIVE'},
  {'kind': 'exact', 'num': 0, 'den': 1, 'expected': 'ABORT'},
  {'kind': 'interval', 'lo_num': 11, 'lo_den': 10, 'hi_num': 6, 'hi_den': 5, 'expected': 'POSITIVE'},
  {'kind': 'interval', 'lo_num': -7, 'lo_den': 2, 'hi_num': -10, 'hi_den': 3, 'expected': 'NEGATIVE'},
  {'kind': 'interval', 'lo_num': -1, 'lo_den': 2, 'hi_num': 1, 'hi_den': 2, 'expected': 'ABORT'},
  {'kind': 'interval', 'lo_num': 0, 'lo_den': 1, 'hi_num': 3, 'hi_den': 7, 'expected': 'ABORT'},
  {'kind': 'float_literal', 'repr': 'FLOAT_LITERAL', 'expected': 'ABORT'},
  {'kind': 'decimal_string', 's': '1/10000000000000000000000000000', 'expected': 'POSITIVE'}
 ]
}

verify(WITNESS)
